import json

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def set_values(instance, values):
    ok = execute_tool('editor_toolset.toolsets.object.ObjectTools.set_properties', json.dumps({'instance': instance, 'values': json.dumps(values)}))['returnValue']
    if not ok:
        raise RuntimeError('Failed to set properties on ' + instance.get('refPath', 'unknown'))

def compile_blueprint(path):
    execute_tool('editor_toolset.toolsets.blueprint.BlueprintTools.compile_blueprint', json.dumps({'blueprint': load(path), 'warnings_as_errors': True}))

def save(paths):
    if not execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths': paths}))['returnValue']:
        raise RuntimeError('Failed to save configured Week 2 assets')

def run():
    experience_path = '/ExtractionOps/Experiences/B_ExtractionExperience'
    action_set_path = '/ExtractionOps/Experiences/DA_ExtractionActionSet'
    pawn_data_path = '/ExtractionOps/Pawns/DA_ExtractionPawnData'
    hud_layout_path = '/ExtractionOps/UI/W_ExtractionHUDLayout'
    debug_hud_path = '/ExtractionOps/UI/WBP_ExtractionDebugHUD'
    experience = load(experience_path)
    hud_action = {'refPath': '/ExtractionOps/Experiences/DA_ExtractionActionSet.DA_ExtractionActionSet:GameFeatureAction_AddWidgets_0'}

    set_values(experience, {
        'gameFeaturesToEnable': ['ShooterCore', 'ExtractionOps'],
        'defaultPawnData': {'refPath': '/ExtractionOps/Pawns/DA_ExtractionPawnData.DA_ExtractionPawnData'}
    })
    set_values(experience, {'actionSets': []})
    set_values(experience, {'actionSets': [
        {'refPath': '/ShooterCore/Experiences/LAS_ShooterGame_SharedInput.LAS_ShooterGame_SharedInput'},
        {'refPath': '/ShooterCore/Experiences/LAS_ShooterGame_StandardComponents.LAS_ShooterGame_StandardComponents'},
        {'refPath': '/ExtractionOps/Experiences/DA_ExtractionActionSet.DA_ExtractionActionSet'}
    ]})
    set_values(load(action_set_path), {'gameFeaturesToEnable': ['ShooterCore', 'ExtractionOps']})
    set_values(hud_action, {'layout': [
        {'layoutClass': {'refPath': '/ExtractionOps/UI/W_ExtractionHUDLayout.W_ExtractionHUDLayout_C'}, 'layerId': {'tagName': 'UI.Layer.Game'}}
    ]})
    set_values(hud_action, {'widgets': []})
    set_values(hud_action, {'widgets': [
        {'widgetClass': '/ShooterCore/UserInterface/HUD/W_QuickBar.W_QuickBar_C', 'slotId': {'tagName': 'HUD.Slot.Equipment'}},
        {'widgetClass': '/ShooterCore/UserInterface/HUD/W_WeaponReticleHost.W_WeaponReticleHost_C', 'slotId': {'tagName': 'HUD.Slot.Reticle'}},
        {'widgetClass': '/ExtractionOps/UI/WBP_ExtractionDebugHUD.WBP_ExtractionDebugHUD_C', 'slotId': {'tagName': 'HUD.Slot.PerfStats.Text'}}
    ]})
    set_values(load(pawn_data_path), {'inputConfig': {'refPath': '/ExtractionOps/Pawns/DA_ExtractionInputConfig.DA_ExtractionInputConfig'}})

    compile_blueprint(experience_path)
    compile_blueprint(hud_layout_path)
    compile_blueprint(debug_hud_path)
    paths = [experience_path, action_set_path, pawn_data_path, hud_layout_path, debug_hud_path, '/ExtractionOps/Pawns/DA_ExtractionInputConfig']
    save(paths)
    return {'configured': paths, 'experienceFeatures': ['ShooterCore', 'ExtractionOps'], 'debugWidgetSlot': 'HUD.Slot.PerfStats.Text'}
